name = "gw-a"
public_key = "{KEY_A}"
endpoint = "172.31.250.11"
role = "responder"
prefixes = ["10.77.1.0/24"]

[[rule]]
id = 1
peer = "gw-a"
source = "10.77.1.10/32"
destination = "10.77.2.10/32"
protocol = "tcp"
ports = "8080"
"#
