            five.push_str(&format!(
                "\n[[peer]]\nname = \"p{i}\"\npublic_key = \"{:02x}{}\"\nendpoint = \"172.31.250.{}\"\nrole = \"initiator\"\nprefixes = [\"10.78.{i}.0/24\"]\n",
