            f(&mut b);
            parse_handshake(&b).unwrap_err()
        };
        assert_eq!(bad(&|b| b[0] = b'X'), WireError::Magic);
        assert_eq!(bad(&|b| b[4] = 3), WireError::Kind(3));
        assert_eq!(bad(&|b| b[4] = 0), WireError::Kind(0));
        assert_eq!(bad(&|b| b[5] = 1), WireError::Flags);
