#[test]
fn classifies_ack_error_and_control_types() {
    let orig = message(0x20, NLM_F_REQUEST | NLM_F_ACK, 42, 0, &[]);
    let mut ack = ne32(0).to_vec();
    ack.extend_from_slice(&orig);
    let m = split_messages(&message(NLMSG_ERROR, 0, 42, 9, &ack)).unwrap();
    assert_eq!(classify(&m[0]), Ok(Reply::Ack { seq: 42 }));

    let mut err = (-2i32).to_ne_bytes().to_vec();
    err.extend_from_slice(&orig);
    let m = split_messages(&message(NLMSG_ERROR, 0, 42, 9, &err)).unwrap();
    assert_eq!(classify(&m[0]), Ok(Reply::Error { seq: 42, errno: 2 }));

    for code in [1i32, i32::MIN] {
        let mut bad = code.to_ne_bytes().to_vec();
        bad.extend_from_slice(&orig);
        let m = split_messages(&message(NLMSG_ERROR, 0, 42, 9, &bad)).unwrap();
        assert_eq!(classify(&m[0]), Err(MessageError::ErrorMessage));
    }
    let m = split_messages(&message(NLMSG_ERROR, 0, 42, 9, &ack[..19])).unwrap();
    assert_eq!(classify(&m[0]), Err(MessageError::ErrorMessage));

    let m = split_messages(&message(NLMSG_DONE, 0, 1, 0, &[0; 4])).unwrap();
    assert_eq!(classify(&m[0]), Ok(Reply::Done));
    let m = split_messages(&message(NLMSG_OVERRUN, 0, 1, 0, &[])).unwrap();
    assert_eq!(
        classify(&m[0]),
        Err(MessageError::ControlType(NLMSG_OVERRUN))
    );
    let m = split_messages(&message(0x30, 0, 1, 0, &[])).unwrap();
    assert!(matches!(classify(&m[0]), Ok(Reply::Data(_))));
}

