#!/usr/bin/env python3
"""Validate an HR1 perimeter snapshot and render an install-once nft batch.

This tool never changes networking. The generated firewall supplements the
module's authorization gates; it cannot replace trusted packet context.
"""

import argparse
from dataclasses import dataclass
import ipaddress
import json
from pathlib import Path
import re
import sys


MAX_CONFIG_BYTES = 32768
PORT = 51888
TABLE = "vpt_perimeter"
UNSUPPORTED = tuple(ipaddress.IPv4Network(value) for value in (
    "0.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16",
    "224.0.0.0/4", "240.0.0.0/4",
))


class ConfigError(ValueError):
    """The entire snapshot must be rejected without emitting a partial batch."""


@dataclass(frozen=True)
class Peer:
    slot: int
    endpoint: ipaddress.IPv4Address
    prefixes: tuple


@dataclass(frozen=True)
class Perimeter:
    lan_interface: str
    lan: ipaddress.IPv4Interface
    underlay_interface: str
    underlay: ipaddress.IPv4Interface
    peers: tuple


def _object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ConfigError(f"duplicate field: {key}")
        result[key] = value
    return result


def _fields(value, expected, where):
    if not isinstance(value, dict) or set(value) != set(expected):
        raise ConfigError(f"{where}: expected exactly {', '.join(expected)}")


def _interface(value):
    if not isinstance(value, str) or not re.fullmatch(r"[A-Za-z0-9_.-]{1,15}", value):
        raise ConfigError("interface must be 1..15 ASCII letters, digits, _, . or -")
    if value in {".", "..", "lo", "vpn0"}:
        raise ConfigError("physical interface cannot be ., .., lo or vpn0")
    return value


def _network(value):
    if not isinstance(value, str) or "/" not in value:
        raise ConfigError("prefix must be a canonical IPv4 CIDR")
    network = ipaddress.IPv4Network(value, strict=True)
    if str(network) != value or network.prefixlen == 0:
        raise ConfigError("prefix must be canonical and non-default")
    if any(network.overlaps(blocked) for blocked in UNSUPPORTED):
        raise ConfigError("prefix includes unsupported unicast addresses")
    return network


def _link(value, where):
    _fields(value, ("interface", "address"), where)
    name = _interface(value["interface"])
    address = value["address"]
    if not isinstance(address, str) or "/" not in address:
        raise ConfigError(f"{where}: address must be an IPv4 interface CIDR")
    link = ipaddress.IPv4Interface(address)
    if str(link) != address:
        raise ConfigError(f"{where}: address must be canonical")
    _network(str(link.network))
    if link.network.prefixlen < 31 and link.ip in (
        link.network.network_address, link.network.broadcast_address,
    ):
        raise ConfigError(f"{where}: gateway is a network or broadcast address")
    return name, link


def parse_config(raw):
    """Return a bounded immutable snapshot; never retain caller-owned lists."""
    if not isinstance(raw, (str, bytes)):
        raise ConfigError("configuration must be JSON text or UTF-8 bytes")
    try:
        if len(raw.encode("utf-8") if isinstance(raw, str) else raw) > MAX_CONFIG_BYTES:
            raise ConfigError("configuration exceeds 32768 bytes")
        value = json.loads(raw, object_pairs_hook=_object)
        _fields(value, ("version", "lan", "underlay", "peers"), "snapshot")
        if type(value["version"]) is not int or value["version"] != 1:
            raise ConfigError("unsupported perimeter schema version")
        lan_name, lan = _link(value["lan"], "lan")
        outer_name, outer = _link(value["underlay"], "underlay")
        if lan_name == outer_name or lan.network.overlaps(outer.network):
            raise ConfigError("LAN and underlay must be separate interfaces/networks")
        if lan.network.prefixlen == 32:
            raise ConfigError("LAN must contain a non-gateway host")
        entries = value["peers"]
        if not isinstance(entries, list) or not 1 <= len(entries) <= 4:
            raise ConfigError("expected 1..4 peers")
        peers, slots, endpoints = [], set(), set()
        owned = [lan.network, outer.network]
        for entry in entries:
            _fields(entry, ("slot", "endpoint", "prefixes"), "peer")
            slot = entry["slot"]
            if type(slot) is not int or not 1 <= slot <= 4 or slot in slots:
                raise ConfigError("peer slots must be unique integers in 1..4")
            endpoint = entry["endpoint"]
            if not isinstance(endpoint, str):
                raise ConfigError("endpoint must be an IPv4 address")
            endpoint = ipaddress.IPv4Address(endpoint)
            _network(f"{endpoint}/32")
            if endpoint in endpoints or endpoint == outer.ip:
                raise ConfigError("duplicate or local outer endpoint")
            if (endpoint in outer.network and outer.network.prefixlen < 31
                    and endpoint in (outer.network.network_address,
                                     outer.network.broadcast_address)):
                raise ConfigError("endpoint is an underlay network/broadcast address")
            prefixes = entry["prefixes"]
            if not isinstance(prefixes, list) or not 1 <= len(prefixes) <= 4:
                raise ConfigError("expected 1..4 prefixes per peer")
            networks = tuple(_network(prefix) for prefix in prefixes)
            for network in networks:
                if any(network.overlaps(previous) for previous in owned):
                    raise ConfigError("remote ownership overlaps another prefix or link")
                owned.append(network)
            peers.append(Peer(slot, endpoint, networks))
            slots.add(slot)
            endpoints.add(endpoint)
        protected = [lan.network] + [net for peer in peers for net in peer.prefixes]
        if any(endpoint in network for endpoint in endpoints for network in protected):
            raise ConfigError("outer endpoint overlaps protected ownership")
        return Perimeter(lan_name, lan, outer_name, outer, tuple(sorted(
            peers, key=lambda peer: peer.slot,
        )))
    except (ValueError, TypeError, RecursionError) as exc:
        raise ConfigError(str(exc)) from exc


def render(config):
    """Render a complete batch; all accept paths remain behind kernel gates.

    nft must execute the batch in one transaction in the selected gateway
    namespace. `create table` intentionally fails if the guard already exists.
    """
    lan, outer = config.lan_interface, config.underlay_interface
    local, carrier = config.lan.ip, config.underlay.ip
    lines = [
        "# HR1 schema v1; install only in the intended gateway namespace.",
        "# Requires project hooks and final admission; marks alone are not trust.",
        f"create table inet {TABLE}",
    ]
    for chain, hook in (("input", "input"), ("forward", "forward"),
                        ("output", "output")):
        lines.append(f"add chain inet {TABLE} {chain} {{ type filter hook {hook} "
                     "priority 0; policy drop; }")

    def rule(chain, expression):
        lines.append(f"add rule inet {TABLE} {chain} {expression}")

    rule("input", 'iifname "lo" counter accept')
    rule("output", 'oifname "lo" counter accept')
    # Local LAN access is separate from remote service forwarding.
    rule("input", f'iifname "{lan}" ip saddr {config.lan.network} '
         f'ip daddr {local} counter accept')
    rule("output", f'oifname "{lan}" ip saddr {local} '
         f'ip daddr {config.lan.network} counter accept')
    # These guards are defense in depth. The -450 module hook must reject outer
    # fragments/options before shared defrag; priority 0 cannot prove that order.
    for chain, direction in (("input", "iifname"), ("output", "oifname")):
        rule(chain, f'{direction} "{outer}" ip hdrlength != 5 counter drop')
        rule(chain, f'{direction} "{outer}" ip frag-off & 0x3fff != 0 counter drop')

    for peer in config.peers:
        mark = 0x56000000 | (peer.slot << 16)
        rule("input", f'iifname "{outer}" ip saddr {peer.endpoint} '
             f'ip daddr {carrier} udp sport {PORT} udp dport {PORT} '
             'udp checksum != 0 counter accept')
        rule("output", f'oifname "{outer}" ip saddr {carrier} '
             f'ip daddr {peer.endpoint} meta mark 0x{mark | 0x5000:08x} '
             f'udp sport {PORT} udp dport {PORT} counter accept')
        for prefix in sorted(peer.prefixes, key=lambda net: (int(net.network_address),
                                                           net.prefixlen)):
            rule("forward", f'iifname "{lan}" oifname "vpn0" '
                 f'ip saddr {config.lan.network} ip saddr != {local} '

