//! The controller's perimeter projection against Harsh's HR1 renderer.
//!
//! `tools/hr1_perimeter.py` is an independent validator. Every configuration
//! the controller accepts must yield a projection the renderer accepts, and
//! the perimeter rules both enforce must reject the same violations. Needs
//! `python3` (standard library only).

use std::path::{Path, PathBuf};
use std::process::{Command, Output};

use serde_json::{Value, json};
use vpt_control::config::GatewayConfig;
use vpt_control::perimeter::Projection;

fn repo() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("..")
}

fn render(json: &str) -> Output {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("projection.json");
    std::fs::write(&path, json).unwrap();
    Command::new("python3")
        .arg("-I")
        .arg(repo().join("tools/hr1_perimeter.py"))
        .arg(&path)
        .output()
        .expect("python3 is required to run the HR1 renderer")
}

fn project(example: &str) -> String {
    let c = GatewayConfig::load(&repo().join("control/examples").join(example)).unwrap();
    Projection::from_config(&c).to_json()
}

fn fixture(name: &str) -> String {
    std::fs::read_to_string(repo().join("tests/fixtures/hr1").join(name)).unwrap()
}

fn value(s: &str) -> Value {
    serde_json::from_str(s).unwrap()
}

#[test]
fn samples_project_to_the_hr1_fixtures() {
    assert_eq!(value(&project("gw-a.toml")), value(&fixture("gw-a.json")));
    assert_eq!(value(&project("gw-b-n2.toml")), value(&fixture("gw-b.json")));
}

#[test]
fn renderer_emits_the_same_batch_for_projection_and_fixture() {
    for (example, fix) in [("gw-a.toml", "gw-a.json"), ("gw-b-n2.toml", "gw-b.json")] {
        let ours = render(&project(example));
