    pair.peers = vec![(2, "172.31.250.1", vec!["10.77.2.0/24"])];
    cases.push(pair);
    let mut routed = base();
    routed.peers = vec![(1, "198.51.100.7", vec!["10.77.2.0/24"])];
    cases.push(routed);
    let mut names = base();
    names.lan_if = "eth0.100";
    names.out_if = "wlan_out-1";
    cases.push(names);

    for (i, case) in cases.iter().enumerate() {
        let config = GatewayConfig::parse(&case.toml())
            .unwrap_or_else(|e| panic!("case {i}: controller rejected: {e}"));
        let ours = Projection::from_config(&config).to_json();
        assert_eq!(value(&ours), value(&case.json()), "case {i}");
        let out = render(&ours);
        assert!(
            out.status.success(),
            "case {i}: renderer rejected: {}",
            String::from_utf8_lossy(&out.stderr)
        );
    }
}

#[test]
fn both_reject_perimeter_violations() {
    type Mutate = fn(&mut Case);
    let cases: Vec<(&str, Mutate)> = vec![
        ("loopback LAN interface", |c| c.lan_if = "lo"),
        ("tunnel device as underlay", |c| c.out_if = "vpn0"),
        ("same interface twice", |c| c.out_if = "lan0"),
        ("interface name too long", |c| c.lan_if = "abcdefghijklmnop"),
        ("host-only LAN", |c| c.lan = "10.77.1.1/32"),
        ("LAN network address", |c| c.lan = "10.77.1.0/24"),
        ("LAN and underlay overlap", |c| c.out = "10.77.1.200/16"),
        ("subnet reaches loopback", |c| c.out = "100.0.0.1/1"),
        ("slot 0", |c| c.peers[0].0 = 0),
        ("slot 5", |c| c.peers[0].0 = 5),
        ("duplicate slot", |c| {
            c.peers.push((1, "172.31.250.13", vec!["10.77.3.0/24"]))
        }),
        ("duplicate endpoint", |c| {
            c.peers.push((2, "172.31.250.12", vec!["10.77.3.0/24"]))
        }),
        ("own underlay as endpoint", |c| c.peers[0].1 = "172.31.250.11"),
        ("underlay broadcast endpoint", |c| c.peers[0].1 = "172.31.250.255"),
        ("underlay network endpoint", |c| c.peers[0].1 = "172.31.250.0"),
        ("multicast endpoint", |c| c.peers[0].1 = "224.0.0.5"),
        ("endpoint inside LAN", |c| c.peers[0].1 = "10.77.1.9"),
        ("endpoint inside a peer prefix", |c| c.peers[0].1 = "10.77.2.9"),
        ("default route", |c| c.peers[0].2 = vec!["0.0.0.0/0"]),
        ("non-canonical prefix", |c| c.peers[0].2 = vec!["10.77.2.1/24"]),
        ("prefix reaches multicast", |c| c.peers[0].2 = vec!["192.0.0.0/2"]),
        ("prefix overlaps LAN", |c| c.peers[0].2 = vec!["10.77.0.0/16"]),
        ("prefix overlaps underlay", |c| c.peers[0].2 = vec!["172.31.0.0/16"]),
        ("overlap within a peer", |c| {
            c.peers[0].2 = vec!["10.77.2.0/24", "10.77.2.128/25"]
        }),
        ("overlap across peers", |c| {
            c.peers.push((2, "172.31.250.13", vec!["10.77.2.0/25"]))
        }),
        ("no prefixes", |c| c.peers[0].2 = vec![]),
        ("five prefixes", |c| {
            c.peers[0].2 = vec!["10.9.1.0/24", "10.9.2.0/24", "10.9.3.0/24", "10.9.4.0/24", "10.9.5.0/24"]
        }),
        ("no peers", |c| c.peers.clear()),
        ("five peers", |c| {
            c.peers = (1..=5)
                .map(|i| (i, ["172.31.250.21", "172.31.250.22", "172.31.250.23", "172.31.250.24", "172.31.250.25"][i as usize - 1], vec![["10.91.0.0/16", "10.92.0.0/16", "10.93.0.0/16", "10.94.0.0/16", "10.95.0.0/16"][i as usize - 1]]))
                .collect()
        }),
    ];
    for (name, mutate) in cases {
        let mut case = base();
        mutate(&mut case);
        assert!(
            GatewayConfig::parse(&case.toml()).is_err(),
            "controller accepted: {name}"
        );
        let out = render(&case.json());
        assert_eq!(out.status.code(), Some(2), "renderer accepted: {name}");
    }
}

