use vpt_control::exchange::{Initiator, ResponderParams, respond};
use vpt_control::identity::PrivateKey;
use vpt_control::wire::{HandshakePayload, Mode};

fn arr(name: &str, k: &[u8; 32]) -> String {
    let b: Vec<String> = k.iter().map(|x| format!("0x{x:02x}")).collect();
