            incarnation: [0xb2; 16],
            responder_locator: 0x5555_6666_7777_8888,
            path_budget: 1500,
            continuity_grant: None,
        };
        let r = respond(&b, &a.public_key(), ini.init_bytes(), &params).unwrap();
        let ki = ini.finish(&r.response).unwrap();
        let kr = r.keys;
        // Controller-side facts the kernel test must agree with.
        assert_eq!(*ki.tx, *kr.rx);
