//! Blocking Generic Netlink request/reply transport (Linux only).
//!
//! One socket per controller, one outstanding request at a time. Each request
//! carries a fresh sequence number and asks for an ACK; replies are accepted
//! only from the kernel (port 0), addressed to this socket's port, and for
//! the outstanding sequence number. Receive is bounded by a timeout, a
//! per-request message budget and the 64 KiB datagram limit.

use std::io;
use std::os::fd::OwnedFd;
use std::time::Duration;

use rustix::net::netlink::{self, SocketAddrNetlink};
use rustix::net::sockopt::{self, Timeout};
use rustix::net::{
    AddressFamily, RecvFlags, SendFlags, SocketFlags, SocketType, bind, getsockname, recvfrom,
    sendto, socket_with,
};
use thiserror::Error;

use super::message::{
    FamilyInfo, MAX_MESSAGE_BYTES, MessageError, NLM_F_ACK, NLM_F_MULTI, Reply, Request, classify,
    get_family_request, parse_family, split_messages,
};

/// Upper bound on datagrams read for one request before giving up.
const MAX_DATAGRAMS_PER_REQUEST: usize = 32;
/// Upper bound on data messages kept for one request (no dumps here).
const MAX_REPLIES_PER_REQUEST: usize = 8;

#[derive(Debug, Error)]
pub enum TransportError {
    #[error("{context}: {source}")]
    Io {
        context: &'static str,
        #[source]
        source: io::Error,
    },
    #[error("no reply within the receive timeout")]
    Timeout,
    #[error("reply datagram larger than {MAX_MESSAGE_BYTES} bytes")]
    Truncated,
    #[error("malformed reply: {0}")]
    Message(#[from] MessageError),
    #[error("kernel rejected the request: {}", io::Error::from_raw_os_error(*.errno))]
    Kernel { errno: i32 },
    #[error("unexpected reply: {0}")]
    Unexpected(&'static str),
}

impl TransportError {
    /// The kernel's errno, if the kernel answered with an error.
    pub fn errno(&self) -> Option<i32> {
        match self {
            TransportError::Kernel { errno } => Some(*errno),
            _ => None,
        }
    }
}

fn io_err(context: &'static str) -> impl FnOnce(rustix::io::Errno) -> TransportError {
    move |e| TransportError::Io {
        context,
        source: e.into(),
    }
}

/// An owned copy of one data reply (type >= 16) for the outstanding request.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OwnedReply {
    pub kind: u16,
    pub flags: u16,
    /// Generic Netlink header and attributes.
    pub payload: Vec<u8>,
}

pub struct GenlSocket {
    fd: OwnedFd,
    port: u32,
    seq: u32,
    buf: Vec<u8>,
}

impl GenlSocket {
    /// Open and bind a `NETLINK_GENERIC` socket; the kernel assigns its port.
    pub fn open(recv_timeout: Duration) -> Result<Self, TransportError> {
        let fd = socket_with(
            AddressFamily::NETLINK,
            SocketType::RAW,
            SocketFlags::CLOEXEC,
            Some(netlink::GENERIC),
        )
        .map_err(io_err("socket"))?;
        bind(&fd, &SocketAddrNetlink::new(0, 0)).map_err(io_err("bind"))?;
        let local = getsockname(&fd).map_err(io_err("getsockname"))?;
        let port = SocketAddrNetlink::try_from(local)
            .map_err(|_| TransportError::Unexpected("socket is not a Netlink socket"))?
            .pid();
        sockopt::set_socket_timeout(&fd, Timeout::Recv, Some(recv_timeout))
            .map_err(io_err("SO_RCVTIMEO"))?;
        Ok(Self {
            fd,
            port,
            seq: 0,
            buf: vec![0; MAX_MESSAGE_BYTES],
        })
    }

    /// The kernel-assigned Netlink port of this socket.
    pub fn port(&self) -> u32 {
        self.port
    }

    fn next_seq(&mut self) -> u32 {
        self.seq = self.seq.wrapping_add(1).max(1);
        self.seq
    }

    /// Send `req` and collect its data replies until the kernel's ACK.
    ///
    /// The request is always sent with `NLM_F_ACK`, so success is explicit:
    /// an error reply becomes [`TransportError::Kernel`], and a missing ACK
    /// becomes [`TransportError::Timeout`]. Messages for other sequence
    /// numbers (late replies to an abandoned request) are discarded.
    pub fn transact(&mut self, req: Request) -> Result<Vec<OwnedReply>, TransportError> {
        let seq = self.next_seq();
        let bytes = req.finish(seq);
        let flags = u16::from_ne_bytes([bytes[6], bytes[7]]);
        if flags & NLM_F_ACK == 0 {
            return Err(TransportError::Unexpected(
                "request does not ask for an ACK",
            ));
        }
        let sent = sendto(
            &self.fd,
            &bytes,
            SendFlags::empty(),
            &SocketAddrNetlink::new(0, 0),
        )
        .map_err(io_err("sendto"))?;
        if sent != bytes.len() {
            return Err(TransportError::Unexpected("short Netlink send"));
        }
        drop(bytes);

        let mut replies = Vec::new();
        for _ in 0..MAX_DATAGRAMS_PER_REQUEST {
            let (_, full_len, from) = match recvfrom(&self.fd, &mut self.buf[..], RecvFlags::TRUNC)
            {
                Ok(r) => r,
                Err(e) if e == rustix::io::Errno::AGAIN || e == rustix::io::Errno::WOULDBLOCK => {
                    return Err(TransportError::Timeout);
                }
                Err(e) if e == rustix::io::Errno::INTR => continue,
                Err(e) => return Err(io_err("recvfrom")(e)),
            };
            if full_len > self.buf.len() {
                return Err(TransportError::Truncated);
            }
            let from_kernel = from
                .and_then(|a| SocketAddrNetlink::try_from(a).ok())
                .is_some_and(|a| a.pid() == 0);
            if !from_kernel {
                continue;
            }
            for msg in split_messages(&self.buf[..full_len])? {
                if msg.header.seq != seq {
                    continue; // stale reply to an earlier request
                }
                if msg.header.pid != self.port {
                    return Err(TransportError::Unexpected(
                        "reply addressed to another port",
                    ));
                }
                match classify(&msg)? {
                    Reply::Ack { seq: s } if s == seq => return Ok(replies),
                    Reply::Error { seq: s, errno } if s == seq => {
                        return Err(TransportError::Kernel { errno });
                    }
                    Reply::Ack { .. } | Reply::Error { .. } => {
                        return Err(TransportError::Unexpected("ACK names another request"));
                    }
                    Reply::Noop => {}
                    Reply::Done => return Err(TransportError::Unexpected("DONE without a dump")),
                    Reply::Data(m) => {
                        if m.header.flags & NLM_F_MULTI != 0 {
                            return Err(TransportError::Unexpected("multipart reply"));
                        }
                        if replies.len() == MAX_REPLIES_PER_REQUEST {
                            return Err(TransportError::Unexpected("too many replies"));
                        }
                        replies.push(OwnedReply {
                            kind: m.header.kind,
                            flags: m.header.flags,
                            payload: m.payload.to_vec(),
                        });
                    }
                }
            }
        }
        Err(TransportError::Unexpected(
            "no ACK within the datagram budget",
        ))
    }

    /// Resolve a Generic Netlink family by name through `nlctrl`.
    pub fn resolve_family(&mut self, name: &str) -> Result<FamilyInfo, TransportError> {
        let replies = self.transact(get_family_request(name)?)?;
        match replies.as_slice() {
            [one] if one.kind == super::message::GENL_ID_CTRL => {
                Ok(parse_family(&one.payload, name)?)
            }
            [_] => Err(TransportError::Unexpected(
                "family reply from another family",
            )),
            _ => Err(TransportError::Unexpected(
                "expected exactly one family reply",
            )),
        }
    }
}

