fn forge_to(port: u32, datagram: &[u8]) {
    let fd = socket_with(
        AddressFamily::NETLINK,
        SocketType::RAW,
        SocketFlags::CLOEXEC,
        Some(netlink::GENERIC),
    )
    .expect("sender socket");
    bind(&fd, &SocketAddrNetlink::new(0, 0)).expect("bind sender");
    sendto(
        &fd,
        datagram,
        SendFlags::empty(),
        &SocketAddrNetlink::new(port, 0),
    )
