     1	//! `vptctl run`: the long-running controller.
     2	//!
     3	//! One session claims the gateway in this network namespace, loads the validated
     4	//! configuration (VALIDATE and COMMIT), then runs the handshake state machine while
     5	//! renewing the 5 second lease every second. If the lease or the kernel family is lost the
     6	//! session ends and a new one starts after a pause: ownership is never assumed to survive.
     7	//! Stopping the process releases the socket, which closes admission at once.
     8	
     9	use std::fs::File;
    10	use std::io::Read;
    11	use std::path::{Path, PathBuf};
    12	use std::time::{Duration, Instant};
    13	
    14	use thiserror::Error;
    15	
    16	use crate::client::{Client, ClientError};
    17	use crate::config::{ConfigError, GatewayConfig};
    18	use crate::identity::{IdentityError, PrivateKey};
    19	use crate::session::{Controller, Entropy, Log};
    20	use crate::vptunnel::{VptunnelError, encode_snapshot, parse_exchange_rx};
    21	
    22	const RENEW_EVERY: Duration = Duration::from_secs(1);
    23	const TICK: Duration = Duration::from_millis(100);
    24	const SESSION_PAUSE: Duration = Duration::from_secs(2);
    25	/// The one configuration revision this controller commits per session.
    26	const REVISION: u64 = 1;
    27	
    28	#[derive(Debug, Error)]
    29	pub enum DaemonError {
    30	    #[error("configuration: {0}")]
    31	    Config(#[from] ConfigError),
    32	    #[error("identity: {0}")]
    33	    Identity(#[from] IdentityError),
    34	    #[error("{0}")]
    35	    Client(#[from] ClientError),
    36	    #[error("{0}")]
    37	    Snapshot(#[from] VptunnelError),
    38	    #[error("interface `{0}`: {1}")]
    39	    Interface(String, std::io::Error),
    40	    #[error("/dev/urandom: {0}")]
    41	    Random(std::io::Error),
    42	}
    43	
    44	pub struct Options {
    45	    pub config: PathBuf,
    46	    pub request_budget: Duration,
    47	    /// The gateway device created with `ip link add <name> type vpt1_ay1`.
    48	    pub device: String,
    49	    /// Stop after this many sessions (tests); `None` runs until killed.
    50	    pub max_sessions: Option<u32>,
    51	    /// Re-establish this long after each success; `None` uses the default (90 s).
    52	    pub rekey_after: Option<Duration>,
    53	}
    54	
    55	fn ifindex(name: &str) -> Result<u32, DaemonError> {
    56	    let path = Path::new("/sys/class/net").join(name).join("ifindex");
    57	    let text =
    58	        std::fs::read_to_string(&path).map_err(|e| DaemonError::Interface(name.into(), e))?;
    59	    text.trim().parse().map_err(|_| {
    60	        DaemonError::Interface(
    61	            name.into(),
    62	            std::io::Error::new(std::io::ErrorKind::InvalidData, "bad ifindex"),
    63	        )
    64	    })
    65	}
    66	
    67	fn entropy() -> Result<Entropy, DaemonError> {
    68	    let mut f = File::open("/dev/urandom").map_err(DaemonError::Random)?;
    69	    Ok(Box::new(move |buf: &mut [u8]| {
    70	        // A failing read of the OS random source must never fall back to anything weaker.
    71	        f.read_exact(buf).expect("cannot read /dev/urandom");
    72	    }))
    73	}
    74	
    75	fn logger(start: Instant) -> Log {
    76	    Box::new(move |m| eprintln!("[{:7.2}s] vptctl: {m}", start.elapsed().as_secs_f64()))
    77	}
    78	
    79	/// Run sessions until killed (or `max_sessions`).
    80	pub fn run(opts: &Options) -> Result<(), DaemonError> {
    81	    let start = Instant::now();
    82	    let mut say = logger(start);
    83	    let mut sessions = 0u32;
    84	    loop {
    85	        sessions += 1;
    86	        match session(opts, start) {
    87	            Ok(()) => return Ok(()),
    88	            Err(e @ (DaemonError::Config(_) | DaemonError::Identity(_))) => return Err(e),
    89	            Err(e) => say(format!("session ended: {e}")),
    90	        }
    91	        if opts.max_sessions.is_some_and(|m| sessions >= m) {
    92	            return Ok(());
    93	        }
    94	        std::thread::sleep(SESSION_PAUSE);
    95	    }
    96	}
    97	
    98	fn session(opts: &Options, start: Instant) -> Result<(), DaemonError> {
    99	    let config = GatewayConfig::load(&opts.config)?;
   100	    let key = PrivateKey::load(&config.gateway.private_key_file)?;
   101	    config.check_local_identity(&key.public_key())?;
   102	    let mut say = logger(start);
   103	
   104	    let device = ifindex(&opts.device)?;
   105	    let lan = ifindex(&config.gateway.lan_interface)?;
   106	    let underlay = ifindex(&config.gateway.underlay_interface)?;
   107	    let mut rng = entropy()?;
   108	    let mut controller_id = [0u8; 16];
   109	    rng(&mut controller_id);
   110	
   111	    let mut client = Client::open(opts.request_budget, device, controller_id)?;
   112	    client.claim()?;
   113	    let snapshot = encode_snapshot(&config, lan, underlay, &key.public_key())?;
   114	    client.validate(REVISION, &snapshot)?;
   115	    client.commit(REVISION)?;
   116	    let status = client.status()?;
   117	    let incarnations: Vec<_> = status
   118	        .peers
   119	        .iter()
   120	        .map(|p| (p.slot, p.incarnation))
   121	        .collect();
   122	    say(format!(
   123	        "gateway `{}` claimed, revision {REVISION} committed, {} peer(s)",
   124	        config.gateway.name,
   125	        incarnations.len()
   126	    ));
   127	
   128	    let mut controller = Controller::new(
   129	        key,
   130	        &config,
   131	        &incarnations,
   132	        rng,
   133	        logger(start),
   134	        Instant::now(),
   135	    );
   136	    if let Some(d) = opts.rekey_after {
   137	        controller.set_rekey_after(d);
   138	    }
   139	    let mut last_renew = Instant::now();
   140	    loop {
   141	        let now = Instant::now();
   142	        if now.duration_since(last_renew) >= RENEW_EVERY {
   143	            client.renew(REVISION)?;
   144	            last_renew = now;
   145	        }
   146	        controller.tick(&mut client, now);
   147	        if let Some(event) = client.recv_event(TICK)? {
   148	            match parse_exchange_rx(&event.payload) {
   149	                Ok(ev) => controller.on_exchange(&mut client, ev, Instant::now()),
   150	                Err(e) => say(format!("ignored a kernel event: {e}")),
   151	            }
   152	        }
   153	        if client.take_events_lost() {
   154	            // Handshake messages are retransmitted, so a lost event heals itself.
   155	            say("kernel events were lost; waiting for retransmission".into());
   156	        }
   157	    }
   158	}
