        fn advance(&mut self, d: Duration) {
            self.now += d;
            self.a.tick(&mut self.pa, self.now);
            self.b.tick(&mut self.pb, self.now);
            self.pump();
        }
    }

    #[test]
    fn both_sides_install_mirrored_keys_and_locators() {
        let mut p = pair();
        p.advance(Duration::ZERO);
