    let g = &c.gateway;
    println!("gateway     {}", g.name);
    println!("lan         {} on {}", g.lan_address, g.lan_interface);
    println!(
        "underlay    {}:{VPT1_PORT} on {}",
        g.underlay_address, g.underlay_interface
    );
    for p in &c.peers {
        let prefixes: Vec<String> = p.prefixes.iter().map(ToString::to_string).collect();
