pub struct PeerStatus {
    pub slot: u8,
    /// 0 down, 1 ready, 2 disabled, 3 invalid (`enum vpt1_peer_state`).
    pub state: u8,
    pub has_generation: bool,
    pub incarnation: [u8; ATTR_PEER_INCARNATION_LEN],
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Status {
    pub owned: bool,
    pub stopping: bool,
    pub owner_epoch: u64,
    pub lease_ms: u64,
    pub revision: u64,
    pub staged_revision: Option<u64>,
    pub peers: Vec<PeerStatus>,
}

fn u64_of(b: &[u8], what: &'static str) -> Result<u64, VptunnelError> {
    <[u8; 8]>::try_from(b)
        .map(u64::from_ne_bytes)
        .map_err(|_| VptunnelError::Malformed(what))
}

/// Decode the payload of a STATUS reply (Generic Netlink header plus attributes).
pub fn parse_status(payload: &[u8]) -> Result<Status, VptunnelError> {
    let attrs = attributes(payload.get(4..).ok_or(VptunnelError::Malformed("status"))?)?;
    let nested = attrs
        .iter()
        .find(|a| a.kind == ATTR_STATUS)
        .ok_or(VptunnelError::Malformed("status: no STATUS attribute"))?;
    let mut st = Status {
        owned: false,
        stopping: false,
        owner_epoch: 0,
        lease_ms: 0,
        revision: 0,
        staged_revision: None,
        peers: Vec::new(),
    };
    for m in attributes(nested.payload)? {
        match m.kind {
            ST_OWNED => st.owned = m.payload.first() == Some(&1),
            ST_STOPPING => st.stopping = m.payload.first() == Some(&1),
            ST_OWNER_EPOCH => st.owner_epoch = u64_of(m.payload, "owner epoch")?,
            ST_LEASE_MS => st.lease_ms = u64_of(m.payload, "lease")?,
            ST_REVISION => st.revision = u64_of(m.payload, "revision")?,
            ST_STAGED => st.staged_revision = Some(u64_of(m.payload, "staged revision")?),
            ST_PEER => {
                let mut peer = PeerStatus {
                    slot: 0,
                    state: 0,
                    has_generation: false,
                    incarnation: [0; ATTR_PEER_INCARNATION_LEN],
                };
                for f in attributes(m.payload)? {
                    match f.kind {
                        PST_SLOT => {
                            peer.slot = <[u8; 2]>::try_from(f.payload)
                                .map(u16::from_ne_bytes)
                                .ok()
                                .and_then(|v| u8::try_from(v).ok())
                                .ok_or(VptunnelError::Malformed("peer slot"))?;
                        }
                        PST_STATE => peer.state = *f.payload.first().unwrap_or(&0),
                        PST_HAS_GEN => peer.has_generation = f.payload.first() == Some(&1),
                        PST_INCARNATION => {
                            peer.incarnation = f
                                .payload
                                .try_into()
                                .map_err(|_| VptunnelError::Malformed("peer incarnation"))?;
                        }
                        _ => {}
                    }
                }
---
    let mut watcher = Watcher::new(&opts.config, bytes);
    let mut silence = Silence::new();
    let mut last_renew = clock.now();
    loop {
        let now = clock.now();
        if now.duration_since(last_renew) >= RENEW_EVERY {
            client.renew(revision)?;
            last_renew = now;
            if let Some(new_bytes) = watcher.poll(now) {
                let ctx = Reload { public };
                match reload(
                    &mut client,
                    &mut revision,
                    &mut controller,
                    &ctx,
                    &new_bytes,
                    now,
                )? {
                    Reloaded::Applied(r) => {
                        watcher.applied(new_bytes);
                        say(format!(
                            "configuration reloaded as revision {revision}: kept {:?}, replaced {:?}, added {:?}, removed {:?}",
                            r.kept, r.replaced, r.added, r.removed
                        ));
                    }
                    Reloaded::Rejected(why) => {
                        watcher.rejected(new_bytes);
                        say(format!(
                            "configuration change rejected, still running revision {revision}: {why}"
                        ));
                    }
                    Reloaded::Transient(why) => match watcher.retry_later(new_bytes, now) {
                        Retry::Later { attempt } => say(format!(
                            "configuration change deferred, still running revision {revision} (attempt {attempt} of {RELOAD_MAX_ATTEMPTS}, retrying in {}s): {why}",
                            RELOAD_RETRY_DELAY.as_secs()
                        )),
                        Retry::GaveUp => say(format!(
                            "configuration change rejected after {RELOAD_MAX_ATTEMPTS} attempts, still running revision {revision}: {why}"
                        )),
                    },
                }
            }
            if let Some(c) = Counters::read(&opts.device)
                && usage.update(c, controller.counts().established)
            {
                let n = controller.request_rekey();
                say(format!("key usage reached a limit; re-keying {n} peer(s)"));
            }
            if let Some(c) = Counters::read(&opts.device)
                && silence.update(now, c, controller.counts().established)
            {
                let n = controller.request_rekey();
                if n > 0 {
                    say(format!(
                        "no records from the peer while sending; trying new keys with {n} peer(s)"
                    ));
                }
            }
        }
        controller.tick(&mut client, now);
        if let Some(event) = client.recv_event(TICK)? {
            match parse_exchange_rx(&event.payload) {
                Ok(ev) => controller.on_exchange(&mut client, ev, clock.now()),
                Err(e) => say(format!("ignored a kernel event: {e}")),
            }
        }
        if client.take_events_lost() {
            // Handshake messages are retransmitted, so a lost event heals itself.
            say("kernel events were lost; waiting for retransmission".into());
        }
    }
