pub struct KernelCounters {
    pub liveness_lost: Option<u64>,
}

/// Decode the payload of a COUNTERS reply, keeping only the members the controller reads.
pub fn parse_counters(payload: &[u8]) -> Result<KernelCounters, VptunnelError> {
    let attrs = attributes(payload.get(4..).ok_or(VptunnelError::Malformed("counters"))?)?;
    let nested = attrs
        .iter()
        .find(|a| a.kind == ATTR_COUNTERS)
        .ok_or(VptunnelError::Malformed("counters: no COUNTERS attribute"))?;
    let mut out = KernelCounters::default();
    for m in attributes(nested.payload)? {
        if m.kind == CTR_LIVENESS_LOST {
            out.liveness_lost = Some(u64_of(m.payload, "liveness counter")?);
        }
    }
    Ok(out)
}

