/// as news. The count is gateway-wide, so with several peers a closure re-keys all initiator
/// peers.
#[derive(Debug, Default)]
pub struct LivenessWatch {
    last: Option<u64>,
}

impl LivenessWatch {
    pub fn new() -> Self {
        Self::default()
    }

    /// True once per rise of the counter, however many closures happened between two samples.
    pub fn update(&mut self, lost: u64) -> bool {
        let rose = self.last.is_some_and(|prev| lost > prev);
        self.last = Some(lost);
        rose
    }
